  # Windows – run PowerShell script located in the artifacts directory.
  pwsh -NoProfile -ExecutionPolicy Bypass -File "$(dirname "$0")/../.gemini/antigravity-ide/brain/2a8d61f6-b048-49b6-a8ee-5cc497213b32/consistency_check_ps.ps1"
