fi

# Consistency Check Wrapper
# Executes linting, style checking, accessibility analysis and token verification.
# Generated by Antigravity – Ulpiano CCO consistency plan.

# Exit on any error
set -e

echo "=== Running ESLint ==="
if command -v eslint >/dev/null 2>&1; then
  eslint . --ext .js,.jsx,.ts,.tsx || true
else
  echo "ESLint not installed – skipping"
fi

echo "=== Running Stylelint ==="
if command -v stylelint >/dev/null 2>&1; then
  stylelint "**/*.{css,scss,html}" || true
else
  echo "Stylelint not installed – skipping"
fi

echo "=== Running Prettier check ==="
if command -v prettier >/dev/null 2>&1; then
  prettier --check "**/*.{js,jsx,ts,tsx,css,scss,html,md}" || true
else
  echo "Prettier not installed – skipping"
fi

echo "=== Running axe-core (HTML) ==="
# Using node script axe-cli if available
if command -v axe-cli >/dev/null 2>&1; then
  axe-cli index.html --exclude "node_modules" || true
else
  echo "axe-cli not installed – skipping"
fi

echo "=== Optimizing SVGs with svgo ==="
if command -v svgo >/dev/null 2>&1; then
  svgo -f svg || true
else
  echo "svgo not installed – skipping"
fi

echo "=== Verifying Design System Tokens ==="
python3 scripts/verify_tokens.py || true

echo "=== Consistency check completed ==="
